import React, { useState } from 'react';
import './styles/theme.css';

// Import Screens (Aapke project ke structure ke anusaar imports adjust kar sakte hain)
import Login from './screens/Login';
import Transactions from './screens/Transactions';
import Stock from './screens/Stock'; // Ya StockAndInventory
// Dusre screens ke liye placeholder ya imports:

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentScreen, setCurrentScreen] = useState('dashboard');

  // Agar user logged in nahi hai toh Login screen dikhayein
  if (!isLoggedIn) {
    return <Login onLoginSuccess={() => setIsLoggedIn(true)} />;
  }

  return (
    <div style={appContainerStyle}>
      
      {/* SIDEBAR NAVIGATION */}
      <div style={sidebarStyle}>
        <div>
          {/* Logo / Brand */}
          <div style={{ padding: '20px 20px 10px 20px' }}>
            <h2 style={{ color: '#FFF', margin: 0, fontSize: '18px', fontWeight: '800' }}>RK SONS</h2>
            <p style={{ color: '#34D399', margin: '2px 0 0 0', fontSize: '11px', fontWeight: '600' }}>Grain Enterprise OS</p>
          </div>

          <div style={menuGroupStyle}>
            <div style={menuTitleStyle}>MAIN MENU</div>
            <div onClick={() => setCurrentScreen('farmers')} style={menuItem(currentScreen === 'farmers')}>🌾 Farmer Management</div>
            <div onClick={() => setCurrentScreen('dashboard')} style={menuItem(currentScreen === 'dashboard')}>📊 Dashboard Overview</div>
            <div onClick={() => setCurrentScreen('transactions')} style={menuItem(currentScreen === 'transactions')}>💳 Transactions & Parties</div>
            <div onClick={() => setCurrentScreen('stock')} style={menuItem(currentScreen === 'stock')}>📦 Stock & Inventory</div>
            <div onClick={() => setCurrentScreen('reports')} style={menuItem(currentScreen === 'reports')}>📈 Reports & Profit</div>
          </div>

          <div style={menuGroupStyle}>
            <div style={menuTitleStyle}>ACTIONS</div>
            <div onClick={() => setCurrentScreen('newsale')} style={menuItem(currentScreen === 'newsale')}>🛒 New Sale Entry</div>
            <div onClick={() => setCurrentScreen('newpurchase')} style={menuItem(currentScreen === 'newpurchase')}>📦 New Purchase Entry</div>
            <div onClick={() => setCurrentScreen('payment')} style={menuItem(currentScreen === 'payment')}>💸 Record Payment</div>
            <div onClick={() => setCurrentScreen('expenses')} style={menuItem(currentScreen === 'expenses')}>🧾 Expenses & Utilities</div>
          </div>
        </div>

        {/* User Profile / Logout */}
        <div style={{ padding: '20px', borderTop: '1px solid rgba(255,255,255,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ color: '#FFF', fontSize: '13px', fontWeight: '700' }}>RK Sons Admin</div>
            <div style={{ color: '#94A3B8', fontSize: '11px' }}>Manager Mode</div>
          </div>
          <span onClick={() => setIsLoggedIn(false)} style={{ cursor: 'pointer', color: '#EF4444', fontSize: '18px' }} title="Logout">⏻</span>
        </div>
      </div>

      {/* MAIN CONTENT AREA */}
      <div style={contentStyle}>
        
        {/* Top Navbar */}
        <div style={topbarStyle}>
          <div style={{ fontSize: '16px', fontWeight: '700', color: '#0F172A', textTransform: 'capitalize' }}>
            {currentScreen.replace(/([A-Z])/g, ' $1')}
          </div>
          <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
            <span style={badgeOperational}>● System Status: Operational</span>
            <button onClick={() => setCurrentScreen('newsale')} style={quickSaleBtn}>+ Quick Sale</button>
          </div>
        </div>

        {/* Dynamic Screen Render */}
        <div style={{ flex: 1, overflowY: 'auto' }}>
          {currentScreen === 'transactions' && <Transactions />}
          {currentScreen === 'stock' && <Stock />}
          {currentScreen === 'dashboard' && <div style={{ padding: '30px' }}><h2>Dashboard Overview</h2><p>Welcome to RK Sons Grain ERP Dashboard.</p></div>}
          {currentScreen === 'farmers' && <div style={{ padding: '30px' }}><h2>Farmer Management Module</h2></div>}
          {currentScreen === 'reports' && <div style={{ padding: '30px' }}><h2>Reports & Profit Analytics</h2></div>}
          {currentScreen === 'newsale' && <div style={{ padding: '30px' }}><h2>New Sale Entry Terminal</h2></div>}
          {currentScreen === 'newpurchase' && <div style={{ padding: '30px' }}><h2>Advanced Mandi Purchase Entry</h2></div>}
          {currentScreen === 'payment' && <div style={{ padding: '30px' }}><h2>Record Payment Module</h2></div>}
          {currentScreen === 'expenses' && <div style={{ padding: '30px' }}><h2>Expenses & Utilities Module</h2></div>}
        </div>

      </div>

    </div>
  );
}

// --- STYLING CONSTANTS ---
const appContainerStyle = { display: 'flex', width: '100vw', height: '100vh', fontFamily: "'Poppins', sans-serif", overflow: 'hidden', background: '#F8FAFC' };

const sidebarStyle = { width: '260px', background: '#0F172A', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', borderRight: '1px solid #1E293B', boxSizing: 'border-box' };

const menuGroupStyle = { padding: '10px 16px' };

const menuTitleStyle = { fontSize: '10px', fontWeight: '700', color: '#64748B', letterSpacing: '1px', marginBottom: '8px', marginTop: '10px' };

const menuItem = (isActive) => ({
  padding: '10px 14px',
  borderRadius: '10px',
  color: isActive ? '#FFF' : '#94A3B8',
  background: isActive ? '#059669' : 'transparent',
  fontSize: '13px',
  fontWeight: '600',
  cursor: 'pointer',
  marginBottom: '4px',
  transition: 'all 0.2s',
  display: 'flex',
  alignItems: 'center',
  gap: '10px'
});

const contentStyle = { flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' };

const topbarStyle = { height: '70px', background: '#FFFFFF', borderBottom: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 30px', boxSizing: 'border-box' };

const badgeOperational = { background: '#ECFDF5', color: '#059669', padding: '6px 12px', borderRadius: '20px', fontSize: '12px', fontWeight: '600', border: '1px solid #A7F3D0' };

const quickSaleBtn = { background: '#059669', color: '#FFF', border: 'none', padding: '10px 16px', borderRadius: '10px', fontWeight: '700', fontSize: '13px', cursor: 'pointer', boxShadow: '0 4px 12px rgba(5,150,105,0.2)' };
